def test_site(site, ks=(1,2,3,5,7,9,12,20,40)):
    V = A[site]; mu=V.mean(0); U,S,Vt=np.linalg.svd(V-mu, full_matrices=False)
    out={}
    for k in ks:
        rec = mu + (V-mu)@Vt[:k].T@Vt[:k]
        if site in ('resid_mid',):
            lg = downstream(rec)
        elif site in ('mlp_out',):
            lg = (A['resid_mid']+rec)@WU
        elif site in ('resid_post',):
            lg = rec@WU
        else:
            lg=None
        if lg is not None:
            out[k]=round((lg.argmax(1)==base).mean(),3)
    return out
